package com.justbash.interpreter.expansion

import com.justbash.encoding.Encoding

private class BoundedStringBuilder(val maxBytes: Int, val context: String) { private val sb = StringBuilder(); private var bytes = 0; fun append(value: String) { val vb = Encoding.utf8ByteLength(value); if (vb > maxBytes - bytes) throw ExecutionLimitError("$context: string length limit exceeded ($maxBytes bytes)", "string_length"); sb.append(value); bytes += vb }; fun build(): String = sb.toString() }
fun applyPatternReplacementBounded(ctx: ExpansionContext, value: String, regex: Regex, replacement: String, replaceAll: Boolean): String { val output = BoundedStringBuilder(ctx.limits.maxStringLength, "pattern replacement"); var lastIndex = 0; var pos = 0; fun findNext(from: Int): MatchResult? { return try { regex.find(value, from) } catch (e: Exception) { null } }; var match = findNext(pos); while (match != null) { ctx.executionScope.consumeLimited("pattern_operations", 1, ctx.limits.maxGlobOperations, "pattern replacement"); val mr = match.range; val matched = match.value; if (replaceAll && matched.isEmpty() && mr.first == value.length) break; output.append(value.substring(lastIndex, mr.first)); output.append(expandReplacement(match, replacement)); lastIndex = mr.last + 1; if (!replaceAll) break; if (matched.isEmpty()) { lastIndex++; pos = Math.max(pos, mr.first + 1) } else { pos = mr.last + 1 }; match = findNext(pos) }; output.append(value.substring(lastIndex)); return output.build() }
internal fun expandReplacement(match: MatchResult, replacement: String): String { val sb = StringBuilder(); var i = 0; while (i < replacement.length) { if (replacement[i] == '\$' && i + 1 < replacement.length) { val next = replacement[i + 1]; when { next == '\$' -> { sb.append('\$'); i += 2 }; next == '&' -> { sb.append(match.value); i += 2 }; next.isDigit() -> { var j = i + 1; var digits = ""; while (j < replacement.length && replacement[j].isDigit() && digits.length < 2) { digits += replacement[j]; j++ }; val gn = digits.toIntOrNull(); val g = if (gn != null && gn in 1 until match.groups.size) match.groupValues.getOrNull(gn) else null; sb.append(g ?: ""); i = j }; else -> { sb.append('\$'); i++ } } } else { sb.append(replacement[i]); i++ } }; return sb.toString() }
